const appends = [{"file": "lib/payments/booking-runtime.ts", "marker": "export function guestFacingBookingError(", "text": "\n\nconst guestSafeBookingPatterns = [\n  /^Guest checkout is currently disabled\\./,\n  /^This booking hold expired\\./,\n  /^This stay/i,\n  /^Pet count/i,\n  /^Too many optional add-ons/i,\n  /^One or more selected add-ons/i,\n  /^Checkout must be after check-in/i,\n  /^Stay is too long/i,\n  /^Guest count/i,\n  /^Pricing is incomplete/i,\n  /^This arrival date requires/i,\n  /^Promo code/i,\n  /^This promo code/i,\n  /^Complete the security check/i,\n  /^The security check/i,\n  /^We could not verify the .+ calendar/i,\n];\n\nexport function guestFacingBookingError(\n  error: unknown,\n  fallback: string,\n) {\n  const message =\n    typeof error === \"string\"\n      ? error.trim()\n      : error instanceof Error\n        ? error.message.trim()\n        : \"\";\n\n  if (\n    message &&\n    guestSafeBookingPatterns.some((pattern) => pattern.test(message))\n  ) {\n    return message;\n  }\n\n  return fallback;\n}\n"}, {"file": "app/find-a-place-theme.css", "marker": "/* Pre-pilot optimized stay-type images */", "text": "\n\n/* Pre-pilot optimized stay-type images */\n.stay-type-slice {\n  background-image: none !important;\n  overflow: hidden;\n}\n.stay-type-slice > img {\n  object-fit: cover;\n}\n.stay-type-slice-1 > img {\n  object-position: 42% center;\n}\n.payment-provider-options:has(> .payment-provider-card:only-child) {\n  grid-template-columns: 1fr;\n}\n"}, {"file": "components/GuestCheckout.module.css", "marker": ".extrasSection {", "text": "\n\n.extrasSection {\n  display: grid;\n  gap: 16px;\n  margin: 20px 0;\n  padding: 18px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  background: #faf8f4;\n}\n\n.extrasList {\n  display: grid;\n  gap: 10px;\n}\n\n.extrasList > strong {\n  font-size: .82rem;\n}\n\n.addOnOption {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr) auto;\n  align-items: start;\n  gap: 10px;\n  padding: 11px 0;\n  border-bottom: 1px solid var(--line);\n}\n\n.addOnOption:last-child {\n  border-bottom: 0;\n}\n\n.addOnOption input {\n  margin-top: 4px;\n}\n\n.addOnOption > span {\n  display: grid;\n  gap: 3px;\n}\n\n.addOnOption b {\n  font-size: .8rem;\n}\n\n.addOnOption small {\n  color: #747873;\n  line-height: 1.45;\n}\n\n.addOnOption em {\n  font-style: normal;\n  font-size: .72rem;\n  font-weight: 800;\n  white-space: nowrap;\n}\n\n.promoField {\n  display: grid;\n  gap: 6px;\n}\n\n.promoField > span {\n  font-size: .72rem;\n  font-weight: 800;\n  color: #656a66;\n}\n\n.promoField small {\n  font-weight: 500;\n  color: #7a7d78;\n}\n\n.promoField input {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 9px;\n  background: #fff;\n  padding: 12px 13px;\n  text-transform: uppercase;\n}\n\n.discountRow b {\n  color: #42634c;\n}\n\n@media (max-width: 620px) {\n  .addOnOption {\n    grid-template-columns: auto minmax(0, 1fr);\n  }\n\n  .addOnOption em {\n    grid-column: 2;\n  }\n}\n"}];
const newFiles = {"lib/notifications/message-emails.ts": "import type { SupabaseClient } from \"@supabase/supabase-js\";\n\nimport {\n  escapeHtml,\n  sendNotificationOnce,\n  siteUrl,\n} from \"@/lib/notifications/transactional-email\";\nimport { createGuestCheckoutToken } from \"@/lib/payments/booking-runtime\";\n\ntype SenderType = \"GUEST\" | \"HOST\";\n\nexport async function sendReservationMessageNotification(\n  admin: SupabaseClient,\n  input: {\n    reservationId: string;\n    messageId: string;\n    senderType: SenderType;\n    body: string;\n  },\n) {\n  const { data: reservation, error } = await admin\n    .from(\"reservations\")\n    .select(\n      \"id,confirmation_code,property_id,organization_id,guest_name,guest_email\",\n    )\n    .eq(\"id\", input.reservationId)\n    .maybeSingle();\n\n  if (error || !reservation) {\n    throw new Error(\"Unable to load reservation message notification data.\");\n  }\n\n  const [{ data: property }, { data: organization }] = await Promise.all([\n    admin\n      .from(\"properties\")\n      .select(\"name,notification_email,operations_email\")\n      .eq(\"id\", reservation.property_id)\n      .maybeSingle(),\n    admin\n      .from(\"organizations\")\n      .select(\"name,contact_email\")\n      .eq(\"id\", reservation.organization_id)\n      .maybeSingle(),\n  ]);\n\n  const propertyName = property?.name || \"your Find A Place stay\";\n  const cleanBody = input.body.trim().slice(0, 4000);\n  const escapedBody = escapeHtml(cleanBody).replace(/\\n/g, \"<br>\");\n  const cleanMessageId = input.messageId.replace(/[^a-zA-Z0-9]/g, \"\");\n\n  if (input.senderType === \"GUEST\") {\n    const recipient =\n      property?.notification_email ||\n      property?.operations_email ||\n      organization?.contact_email ||\n      null;\n\n    if (!recipient) return;\n\n    await sendNotificationOnce({\n      admin,\n      reservationId: reservation.id,\n      type: `HOST_MESSAGE_${cleanMessageId}`,\n      recipient,\n      subject: `New guest message: ${propertyName} \u00b7 ${reservation.confirmation_code}`,\n      text: `${reservation.guest_name || \"Your guest\"} sent a message about ${propertyName}.\\n\\n${cleanBody}\\n\\nOpen the reservation: ${siteUrl()}/host/reservations/${reservation.id}`,\n      html: `<p><strong>New guest message</strong></p><p>${escapeHtml(\n        reservation.guest_name || \"Your guest\",\n      )} sent a message about ${escapeHtml(\n        propertyName,\n      )}.</p><blockquote>${escapedBody}</blockquote><p><a href=\"${escapeHtml(\n        `${siteUrl()}/host/reservations/${reservation.id}`,\n      )}\">Open the reservation</a></p>`,\n    });\n\n    return;\n  }\n\n  if (!reservation.guest_email) return;\n\n  const token = createGuestCheckoutToken(reservation.id);\n  const tripUrl = `${siteUrl()}/trip/${encodeURIComponent(\n    reservation.confirmation_code,\n  )}?reservationId=${encodeURIComponent(\n    reservation.id,\n  )}&checkoutToken=${encodeURIComponent(token)}`;\n\n  await sendNotificationOnce({\n    admin,\n    reservationId: reservation.id,\n    type: `GUEST_MESSAGE_${cleanMessageId}`,\n    recipient: reservation.guest_email,\n    subject: `New host message: ${propertyName}`,\n    text: `Your host sent a message about ${propertyName} (${reservation.confirmation_code}).\\n\\n${cleanBody}\\n\\nOpen your secure trip page: ${tripUrl}`,\n    html: `<p><strong>New host message</strong></p><p>Your host sent a message about ${escapeHtml(\n      propertyName,\n    )}.</p><blockquote>${escapedBody}</blockquote><p><a href=\"${escapeHtml(\n      tripUrl,\n    )}\">Open your secure trip page</a></p>`,\n  });\n}\n"};
const overwriteFiles = {"README.md": "# Find A Place Booking\n\nProduction booking marketplace for Find A Place.\n\n## Current pilot baseline\n\nThe repository includes the guest marketplace, host portal, admin workspace, iCal calendar synchronization, Stripe Connect destination charges, guest verification, policy acceptance, transactional email, scheduled payouts, refunds, marketplace lodging-tax accounting, and operational reporting.\n\nApply Supabase migrations through:\n\n`supabase/migrations/20260920005000_restore_live_safety_hardening.sql`\n\n## Local verification\n\n```bash\nnpm ci\nnpm run typecheck\nnpm run build\n```\n\n## Live checkout gates\n\nLive checkout should only be enabled after the production environment is configured with matching Stripe live keys, signed webhooks, Turnstile, transactional email, CRON_SECRET, the guest token secret, a ready host payout account, verified property tax configuration, and the per-property live checkout switch.\n\nThe payment architecture uses Stripe destination charges. Find A Place retains the platform commission, configured host processing-fee recovery, and marketplace-collected lodging tax in the application fee; the remaining booking proceeds are routed to the connected host account. Scheduled bank payouts remain controlled separately by the payout policy.\n\n## Operations\n\nVercel cron routes handle calendar synchronization, notification retries, and scheduled payouts. The protected Supabase health endpoint verifies the current migration markers for operations use.\n", "MANIFEST.json": "{\n  \"name\": \"Find A Place Booking - Pre-Pilot Cleanup\",\n  \"date\": \"2026-09-21\",\n  \"baseline_commit\": \"a4518d7fd709e703fb77e3f34aeecdab724f3105\",\n  \"migration_floor\": \"supabase/migrations/20260920005000_restore_live_safety_hardening.sql\",\n  \"scope\": [\n    \"guest checkout promo codes and guest-visible add-ons\",\n    \"pre-payment itemized booking summary\",\n    \"guest-safe API error handling\",\n    \"reservation message email notifications\",\n    \"protected operations health endpoint\",\n    \"homepage stay-type image optimization\",\n    \"host/admin copy cleanup\",\n    \"shared contact/support styles\",\n    \"production README and manifest restoration\"\n  ],\n  \"database_migrations_added\": false,\n  \"payment_math_changed\": false,\n  \"stripe_routing_changed\": false,\n  \"tax_math_changed\": false,\n  \"payout_policy_changed\": false\n}\n"};

function findRepo(start) {
  let current = path.resolve(start);
  for (let i = 0; i < 5; i += 1) {
    const pkg = path.join(current, "package.json");
    if (fs.existsSync(pkg)) {
      try {
        const parsed = JSON.parse(fs.readFileSync(pkg, "utf8"));
        if (parsed.name === "find-a-place-booking") return current;
      } catch {}
    }
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  throw new Error(
    "Could not find the Find A Place Booking repo. Extract this ZIP into the repo folder and run APPLY_FIXES.cmd again.",
  );
}

const repo = findRepo(process.argv[2] || process.cwd());
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupRoot = path.join(repo, `.prepilot-cleanup-backup-${stamp}`);
const backedUp = new Set();
const changed = new Set();

function absolute(rel) {
  return path.join(repo, ...rel.split("/"));
}

function backup(rel) {
  if (backedUp.has(rel)) return;
  const src = absolute(rel);
  if (!fs.existsSync(src)) {
    backedUp.add(rel);
    return;
  }
  const dest = path.join(backupRoot, ...rel.split("/"));
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
  backedUp.add(rel);
}

function write(rel, content) {
  const dest = absolute(rel);
  backup(rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, content, "utf8");
  changed.add(rel);
}

function replaceRequired(content, oldText, newText, label, file) {
  if (content.includes(newText)) return content;
  const index = content.indexOf(oldText);
  if (index < 0) {
    throw new Error(`Patch anchor not found for ${label} in ${file}. The repo may have changed since the audited commit.`);
  }
  return content.slice(0, index) + newText + content.slice(index + oldText.length);
}

for (const operation of replacements) {
  const file = absolute(operation.file);
  if (!fs.existsSync(file)) {
    throw new Error(`Required file is missing: ${operation.file}`);
  }
  const current = fs.readFileSync(file, "utf8");
  const next = replaceRequired(
    current,
    operation.old,
    operation.new,
    operation.label,
    operation.file,
  );
  if (next !== current) write(operation.file, next);
}

for (const operation of appends) {
  const file = absolute(operation.file);
  if (!fs.existsSync(file)) {
    throw new Error(`Required file is missing: ${operation.file}`);
  }
  const current = fs.readFileSync(file, "utf8");
  if (!current.includes(operation.marker)) {
    write(operation.file, current.replace(/\s*$/, "") + operation.text + "\n");
  }
}

for (const [rel, content] of Object.entries(newFiles)) {
  const file = absolute(rel);
  if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content) continue;
  write(rel, content);
}

for (const [rel, content] of Object.entries(overwriteFiles)) {
  const file = absolute(rel);
  if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content) continue;
  write(rel, content);
}

console.log("");
console.log(`Applied ${changed.size} pre-pilot source-file updates.`);
console.log(`Backup: ${backupRoot}`);
console.log("");

function run(args, label) {
  console.log(`=== ${label} ===`);

  const command =
    process.platform === "win32"
      ? (process.env.ComSpec || "C:\\Windows\\System32\\cmd.exe")
      : "npm";

  const commandArgs =
    process.platform === "win32"
      ? ["/d", "/s", "/c", `npm ${args.join(" ")}`]
      : args;

  const result = spawnSync(command, commandArgs, {
    cwd: repo,
    stdio: "inherit",
    windowsHide: false,
  });

  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(
      `${label} failed with exit code ${result.status}. The source changes were left in place and the backup is available above.`,
    );
  }
}

run(["run", "typecheck"], "TypeScript check");
run(["run", "build"], "Production build");

console.log("");
console.log("Pre-pilot cleanup applied successfully.");
console.log("No database migration, Stripe routing, tax math, commission math, or payout-policy changes were made.");
